# ! [doc = " # Match exhaustiveness and redundancy algorithm"] # ! [doc = ""] # ! [doc = " This file contains the logic for exhaustiveness and usefulness checking for pattern-matching."] # ! [doc = " Specifically, given a list of patterns in a match, we can tell whether:"] # ! [doc = " (a) a given pattern is redundant"] # ! [doc = " (b) the patterns cover every possible value for the type (exhaustiveness)"] # ! [doc = ""] # ! [doc = " The algorithm implemented here is inspired from the one described in [this"] # ! [doc = " paper](http://moscova.inria.fr/~maranget/papers/warn/index.html). We have however changed it in"] # ! [doc = " various ways to accommodate the variety of patterns that Rust supports. We thus explain our"] # ! [doc = " version here, without being as precise."] # ! [doc = ""] # ! [doc = " Fun fact: computing exhaustiveness is NP-complete, because we can encode a SAT problem as an"] # ! [doc = " exhaustiveness problem. See [here](https://niedzejkob.p4.team/rust-np) for the fun details."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Summary"] # ! [doc = ""] # ! [doc = " The algorithm is given as input a list of patterns, one for each arm of a match, and computes"] # ! [doc = " the following:"] # ! [doc = " - a set of values that match none of the patterns (if any),"] # ! [doc = " - for each subpattern (taking into account or-patterns), whether removing it would change"] # ! [doc = "     anything about how the match executes, i.e. whether it is useful/not redundant."] # ! [doc = ""] # ! [doc = " To a first approximation, the algorithm works by exploring all possible values for the type"] # ! [doc = " being matched on, and determining which arm(s) catch which value. To make this tractable we"] # ! [doc = " cleverly group together values, as we'll see below."] # ! [doc = ""] # ! [doc = " The entrypoint of this file is the [`compute_match_usefulness`] function, which computes"] # ! [doc = " usefulness for each subpattern and exhaustiveness for the whole match."] # ! [doc = ""] # ! [doc = " In this page we explain the necessary concepts to understand how the algorithm works."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Usefulness"] # ! [doc = ""] # ! [doc = " The central concept of this file is the notion of \"usefulness\". Given some patterns `p_1 .."] # ! [doc = " p_n`, a pattern `q` is said to be *useful* if there is a value that is matched by `q` and by"] # ! [doc = " none of the `p_i`. We write `usefulness(p_1 .. p_n, q)` for a function that returns a list of"] # ! [doc = " such values. The aim of this file is to compute it efficiently."] # ! [doc = ""] # ! [doc = " This is enough to compute usefulness: a pattern in a `match` expression is redundant iff it is"] # ! [doc = " not useful w.r.t. the patterns above it:"] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " # fn foo() {"] # ! [doc = " match Some(0u32) {"] # ! [doc = "     Some(0..100) => {},"] # ! [doc = "     Some(90..190) => {}, // useful: `Some(150)` is matched by this but not the branch above"] # ! [doc = "     Some(50..150) => {}, // redundant: all the values this matches are already matched by"] # ! [doc = "                          //   the branches above"] # ! [doc = "     None => {},          // useful: `None` is matched by this but not the branches above"] # ! [doc = " }"] # ! [doc = " # }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This is also enough to compute exhaustiveness: a match is exhaustive iff the wildcard `_`"] # ! [doc = " pattern is _not_ useful w.r.t. the patterns in the match. The values returned by `usefulness`"] # ! [doc = " are used to tell the user which values are missing."] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " # fn foo(x: Option<u32>) {"] # ! [doc = " match x {"] # ! [doc = "     None => {},"] # ! [doc = "     Some(0) => {},"] # ! [doc = "     // not exhaustive: `_` is useful because it matches `Some(1)`"] # ! [doc = " }"] # ! [doc = " # }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Constructors and fields"] # ! [doc = ""] # ! [doc = " In the value `Pair(Some(0), true)`, `Pair` is called the constructor of the value, and `Some(0)`"] # ! [doc = " and `true` are its fields. Every matchable value can be decomposed in this way. Examples of"] # ! [doc = " constructors are: `Some`, `None`, `(,)` (the 2-tuple constructor), `Foo {..}` (the constructor"] # ! [doc = " for a struct `Foo`), and `2` (the constructor for the number `2`)."] # ! [doc = ""] # ! [doc = " Each constructor takes a fixed number of fields; this is called its arity. `Pair` and `(,)` have"] # ! [doc = " arity 2, `Some` has arity 1, `None` and `42` have arity 0. Each type has a known set of"] # ! [doc = " constructors. Some types have many constructors (like `u64`) or even an infinitely many (like"] # ! [doc = " `&str` and `&[T]`)."] # ! [doc = ""] # ! [doc = " Patterns are similar: `Pair(Some(_), _)` has constructor `Pair` and two fields. The difference"] # ! [doc = " is that we get some extra pattern-only constructors, namely: the wildcard `_`, variable"] # ! [doc = " bindings, integer ranges like `0..=10`, and variable-length slices like `[_, .., _]`. We treat"] # ! [doc = " or-patterns separately, see the dedicated section below."] # ! [doc = ""] # ! [doc = " Now to check if a value `v` matches a pattern `p`, we check if `v`'s constructor matches `p`'s"] # ! [doc = " constructor, then recursively compare their fields if necessary. A few representative examples:"] # ! [doc = ""] # ! [doc = " - `matches!(v, _) := true`"] # ! [doc = " - `matches!((v0,  v1), (p0,  p1)) := matches!(v0, p0) && matches!(v1, p1)`"] # ! [doc = " - `matches!(Foo { bar: v0, baz: v1 }, Foo { bar: p0, baz: p1 }) := matches!(v0, p0) && matches!(v1, p1)`"] # ! [doc = " - `matches!(Ok(v0), Ok(p0)) := matches!(v0, p0)`"] # ! [doc = " - `matches!(Ok(v0), Err(p0)) := false` (incompatible variants)"] # ! [doc = " - `matches!(v, 1..=100) := matches!(v, 1) || ... || matches!(v, 100)`"] # ! [doc = " - `matches!([v0], [p0, .., p1]) := false` (incompatible lengths)"] # ! [doc = " - `matches!([v0, v1, v2], [p0, .., p1]) := matches!(v0, p0) && matches!(v2, p1)`"] # ! [doc = ""] # ! [doc = " Constructors and relevant operations are defined in the [`crate::constructor`] module. A"] # ! [doc = " representation of patterns that uses constructors is available in [`crate::pat`]. The question"] # ! [doc = " of whether a constructor is matched by another one is answered by"] # ! [doc = " [`Constructor::is_covered_by`]."] # ! [doc = ""] # ! [doc = " Note 1: variable bindings (like the `x` in `Some(x)`) match anything, so we treat them as wildcards."] # ! [doc = " Note 2: this only applies to matchable values. For example a value of type `Rc<u64>` can't be"] # ! [doc = " deconstructed that way."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Specialization"] # ! [doc = ""] # ! [doc = " The examples in the previous section motivate the operation at the heart of the algorithm:"] # ! [doc = " \"specialization\". It captures this idea of \"removing one layer of constructor\"."] # ! [doc = ""] # ! [doc = " `specialize(c, p)` takes a value-only constructor `c` and a pattern `p`, and returns a"] # ! [doc = " pattern-tuple or nothing. It works as follows:"] # ! [doc = ""] # ! [doc = " - Specializing for the wrong constructor returns nothing"] # ! [doc = ""] # ! [doc = "   - `specialize(None, Some(p0)) := <nothing>`"] # ! [doc = "   - `specialize([,,,], [p0]) := <nothing>`"] # ! [doc = ""] # ! [doc = " - Specializing for the correct constructor returns a tuple of the fields"] # ! [doc = ""] # ! [doc = "   - `specialize(Variant1, Variant1(p0, p1, p2)) := (p0, p1, p2)`"] # ! [doc = "   - `specialize(Foo{ bar, baz, quz }, Foo { bar: p0, baz: p1, .. }) := (p0, p1, _)`"] # ! [doc = "   - `specialize([,,,], [p0, .., p1]) := (p0, _, _, p1)`"] # ! [doc = ""] # ! [doc = " We get the following property: for any values `v_1, .., v_n` of appropriate types, we have:"] # ! [doc = " ```text"] # ! [doc = " matches!(c(v_1, .., v_n), p)"] # ! [doc = " <=> specialize(c, p) returns something"] # ! [doc = "     && matches!((v_1, .., v_n), specialize(c, p))"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " We also extend specialization to pattern-tuples by applying it to the first pattern:"] # ! [doc = " `specialize(c, (p_0, .., p_n)) := specialize(c, p_0) ++ (p_1, .., p_m)`"] # ! [doc = " where `++` is concatenation of tuples."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " The previous property extends to pattern-tuples:"] # ! [doc = " ```text"] # ! [doc = " matches!((c(v_1, .., v_n), w_1, .., w_m), (p_0, p_1, .., p_m))"] # ! [doc = " <=> specialize(c, p_0) does not error"] # ! [doc = "     && matches!((v_1, .., v_n, w_1, .., w_m), specialize(c, (p_0, p_1, .., p_m)))"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Whether specialization returns something or not is given by [`Constructor::is_covered_by`]."] # ! [doc = " Specialization of a pattern is computed in [`DeconstructedPat::specialize`]. Specialization for"] # ! [doc = " a pattern-tuple is computed in [`PatStack::pop_head_constructor`]. Finally, specialization for a"] # ! [doc = " set of pattern-tuples is computed in [`Matrix::specialize_constructor`]."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Undoing specialization"] # ! [doc = ""] # ! [doc = " To construct witnesses we will need an inverse of specialization. If `c` is a constructor of"] # ! [doc = " arity `n`, we define `unspecialize` as:"] # ! [doc = " `unspecialize(c, (p_1, .., p_n, q_1, .., q_m)) := (c(p_1, .., p_n), q_1, .., q_m)`."] # ! [doc = ""] # ! [doc = " This is done for a single witness-tuple in [`WitnessStack::apply_constructor`], and for a set of"] # ! [doc = " witness-tuples in [`WitnessMatrix::apply_constructor`]."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Computing usefulness"] # ! [doc = ""] # ! [doc = " We now present a naive version of the algorithm for computing usefulness. From now on we operate"] # ! [doc = " on pattern-tuples."] # ! [doc = ""] # ! [doc = " Let `pt_1, .., pt_n` and `qt` be length-m tuples of patterns for the same type `(T_1, .., T_m)`."] # ! [doc = " We compute `usefulness(tp_1, .., tp_n, tq)` as follows:"] # ! [doc = ""] # ! [doc = " - Base case: `m == 0`."] # ! [doc = "     The pattern-tuples are all empty, i.e. they're all `()`. Thus `tq` is useful iff there are"] # ! [doc = "     no rows above it, i.e. if `n == 0`. In that case we return `()` as a witness-tuple of"] # ! [doc = "     usefulness of `tq`."] # ! [doc = ""] # ! [doc = " - Inductive case: `m > 0`."] # ! [doc = "     In this naive version, we list all the possible constructors for values of type `T1` (we"] # ! [doc = "     will be more clever in the next section)."] # ! [doc = ""] # ! [doc = "     - For each such constructor `c` for which `specialize(c, tq)` is not nothing:"] # ! [doc = "         - We recursively compute `usefulness(specialize(c, tp_1) ... specialize(c, tp_n), specialize(c, tq))`,"] # ! [doc = "             where we discard any `specialize(c, p_i)` that returns nothing."] # ! [doc = "         - For each witness-tuple `w` found, we apply `unspecialize(c, w)` to it."] # ! [doc = ""] # ! [doc = "     - We return the all the witnesses found, if any."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " Let's take the following example:"] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " # enum Enum { Variant1(()), Variant2(Option<bool>, u32)}"] # ! [doc = " # use Enum::*;"] # ! [doc = " # fn foo(x: Enum) {"] # ! [doc = " match x {"] # ! [doc = "     Variant1(_) => {} // `p1`"] # ! [doc = "     Variant2(None, 0) => {} // `p2`"] # ! [doc = "     Variant2(Some(_), 0) => {} // `q`"] # ! [doc = " }"] # ! [doc = " # }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " To compute the usefulness of `q`, we would proceed as follows:"] # ! [doc = " ```text"] # ! [doc = " Start:"] # ! [doc = "   `tp1 = [Variant1(_)]`"] # ! [doc = "   `tp2 = [Variant2(None, 0)]`"] # ! [doc = "   `tq  = [Variant2(Some(true), 0)]`"] # ! [doc = ""] # ! [doc = "   Constructors are `Variant1` and `Variant2`. Only `Variant2` can specialize `tq`."] # ! [doc = "   Specialize with `Variant2`:"] # ! [doc = "     `tp2 = [None, 0]`"] # ! [doc = "     `tq  = [Some(true), 0]`"] # ! [doc = ""] # ! [doc = "     Constructors are `None` and `Some`. Only `Some` can specialize `tq`."] # ! [doc = "     Specialize with `Some`:"] # ! [doc = "       `tq  = [true, 0]`"] # ! [doc = ""] # ! [doc = "       Constructors are `false` and `true`. Only `true` can specialize `tq`."] # ! [doc = "       Specialize with `true`:"] # ! [doc = "         `tq  = [0]`"] # ! [doc = ""] # ! [doc = "         Constructors are `0`, `1`, .. up to infinity. Only `0` can specialize `tq`."] # ! [doc = "         Specialize with `0`:"] # ! [doc = "           `tq  = []`"] # ! [doc = ""] # ! [doc = "           m == 0 and n == 0, so `tq` is useful with witness `[]`."] # ! [doc = "             `witness  = []`"] # ! [doc = ""] # ! [doc = "         Unspecialize with `0`:"] # ! [doc = "           `witness  = [0]`"] # ! [doc = "       Unspecialize with `true`:"] # ! [doc = "         `witness  = [true, 0]`"] # ! [doc = "     Unspecialize with `Some`:"] # ! [doc = "       `witness  = [Some(true), 0]`"] # ! [doc = "   Unspecialize with `Variant2`:"] # ! [doc = "     `witness  = [Variant2(Some(true), 0)]`"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Therefore `usefulness(tp_1, tp_2, tq)` returns the single witness-tuple `[Variant2(Some(true), 0)]`."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " Computing the set of constructors for a type is done in [`PatCx::ctors_for_ty`]. See"] # ! [doc = " the following sections for more accurate versions of the algorithm and corresponding links."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Computing usefulness and exhaustiveness in one go"] # ! [doc = ""] # ! [doc = " The algorithm we have described so far computes usefulness of each pattern in turn, and ends by"] # ! [doc = " checking if `_` is useful to determine exhaustiveness of the whole match. In practice, instead"] # ! [doc = " of doing \"for each pattern { for each constructor { ... } }\", we do \"for each constructor { for"] # ! [doc = " each pattern { ... } }\". This allows us to compute everything in one go."] # ! [doc = ""] # ! [doc = " [`Matrix`] stores the set of pattern-tuples under consideration. We track usefulness of each"] # ! [doc = " row mutably in the matrix as we go along. We ignore witnesses of usefulness of the match rows."] # ! [doc = " We gather witnesses of the usefulness of `_` in [`WitnessMatrix`]. The algorithm that computes"] # ! [doc = " all this is in [`compute_exhaustiveness_and_usefulness`]."] # ! [doc = ""] # ! [doc = " See the full example at the bottom of this documentation."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Making usefulness tractable: constructor splitting"] # ! [doc = ""] # ! [doc = " We're missing one last detail: which constructors do we list? Naively listing all value"] # ! [doc = " constructors cannot work for types like `u64` or `&str`, so we need to be more clever. The final"] # ! [doc = " clever idea for this algorithm is that we can group together constructors that behave the same."] # ! [doc = ""] # ! [doc = " Examples:"] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " match (0, false) {"] # ! [doc = "     (0 ..=100, true) => {}"] # ! [doc = "     (50..=150, false) => {}"] # ! [doc = "     (0 ..=200, _) => {}"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " In this example, trying any of `0`, `1`, .., `49` will give the same specialized matrix, and"] # ! [doc = " thus the same usefulness/exhaustiveness results. We can thus accelerate the algorithm by"] # ! [doc = " trying them all at once. Here in fact, the only cases we need to consider are: `0..50`,"] # ! [doc = " `50..=100`, `101..=150`,`151..=200` and `201..`."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " enum Direction { North, South, East, West }"] # ! [doc = " # let wind = (Direction::North, 0u8);"] # ! [doc = " match wind {"] # ! [doc = "     (Direction::North, 50..) => {}"] # ! [doc = "     (_, _) => {}"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " In this example, trying any of `South`, `East`, `West` will give the same specialized matrix. By"] # ! [doc = " the same reasoning, we only need to try two cases: `North`, and \"everything else\"."] # ! [doc = ""] # ! [doc = " We call _constructor splitting_ the operation that computes such a minimal set of cases to try."] # ! [doc = " This is done in [`ConstructorSet::split`] and explained in [`crate::constructor`]."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # `Missing` and relevancy"] # ! [doc = ""] # ! [doc = " ## Relevant values"] # ! [doc = ""] # ! [doc = " Take the following example:"] # ! [doc = ""] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " # let foo = (true, true);"] # ! [doc = " match foo {"] # ! [doc = "     (true, _) => 1,"] # ! [doc = "     (_, true) => 2,"] # ! [doc = " };"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Consider the value `(true, true)`:"] # ! [doc = " - Row 2 does not distinguish `(true, true)` and `(false, true)`;"] # ! [doc = " - `false` does not show up in the first column of the match, so without knowing anything else we"] # ! [doc = "     can deduce that `(false, true)` matches the same or fewer rows than `(true, true)`."] # ! [doc = ""] # ! [doc = " Using those two facts together, we deduce that `(true, true)` will not give us more usefulness"] # ! [doc = " information about row 2 than `(false, true)` would. We say that \"`(true, true)` is made"] # ! [doc = " irrelevant for row 2 by `(false, true)`\". We will use this idea to prune the search tree."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " ## Computing relevancy"] # ! [doc = ""] # ! [doc = " We now generalize from the above example to approximate relevancy in a simple way. Note that we"] # ! [doc = " will only compute an approximation: we can sometimes determine when a case is irrelevant, but"] # ! [doc = " computing this precisely is at least as hard as computing usefulness."] # ! [doc = ""] # ! [doc = " Our computation of relevancy relies on the `Missing` constructor. As explained in"] # ! [doc = " [`crate::constructor`], `Missing` represents the constructors not present in a given column. For"] # ! [doc = " example in the following:"] # ! [doc = ""] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " enum Direction { North, South, East, West }"] # ! [doc = " # let wind = (Direction::North, 0u8);"] # ! [doc = " match wind {"] # ! [doc = "     (Direction::North, _) => 1,"] # ! [doc = "     (_, 50..) => 2,"] # ! [doc = " };"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Here `South`, `East` and `West` are missing in the first column, and `0..50`  is missing in the"] # ! [doc = " second. Both of these sets are represented by `Constructor::Missing` in their corresponding"] # ! [doc = " column."] # ! [doc = ""] # ! [doc = " We then compute relevancy as follows: during the course of the algorithm, for a row `r`:"] # ! [doc = " - if `r` has a wildcard in the first column;"] # ! [doc = " - and some constructors are missing in that column;"] # ! [doc = " - then any `c != Missing` is considered irrelevant for row `r`."] # ! [doc = ""] # ! [doc = " By this we mean that continuing the algorithm by specializing with `c` is guaranteed not to"] # ! [doc = " contribute more information about the usefulness of row `r` than what we would get by"] # ! [doc = " specializing with `Missing`. The argument is the same as in the previous subsection."] # ! [doc = ""] # ! [doc = " Once we've specialized by a constructor `c` that is irrelevant for row `r`, we're guaranteed to"] # ! [doc = " only explore values irrelevant for `r`. If we then ever reach a point where we're only exploring"] # ! [doc = " values that are irrelevant to all of the rows (including the virtual wildcard row used for"] # ! [doc = " exhaustiveness), we skip that case entirely."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " ## Example"] # ! [doc = ""] # ! [doc = " Let's go through a variation on the first example:"] # ! [doc = ""] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " # let foo = (true, true, true);"] # ! [doc = " match foo {"] # ! [doc = "     (true, _, true) => 1,"] # ! [doc = "     (_, true, _) => 2,"] # ! [doc = " };"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = "  ┐ Patterns:"] # ! [doc = "  │   1. `[(true, _, true)]`"] # ! [doc = "  │   2. `[(_, true, _)]`"] # ! [doc = "  │   3. `[_]` // virtual extra wildcard row"] # ! [doc = "  │"] # ! [doc = "  │ Specialize with `(,,)`:"] # ! [doc = "  ├─┐ Patterns:"] # ! [doc = "  │ │   1. `[true, _, true]`"] # ! [doc = "  │ │   2. `[_, true, _]`"] # ! [doc = "  │ │   3. `[_, _, _]`"] # ! [doc = "  │ │"] # ! [doc = "  │ │ There are missing constructors in the first column (namely `false`), hence"] # ! [doc = "  │ │ `true` is irrelevant for rows 2 and 3."] # ! [doc = "  │ │"] # ! [doc = "  │ │ Specialize with `true`:"] # ! [doc = "  │ ├─┐ Patterns:"] # ! [doc = "  │ │ │   1. `[_, true]`"] # ! [doc = "  │ │ │   2. `[true, _]` // now exploring irrelevant cases"] # ! [doc = "  │ │ │   3. `[_, _]`    // now exploring irrelevant cases"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ There are missing constructors in the first column (namely `false`), hence"] # ! [doc = "  │ │ │ `true` is irrelevant for rows 1 and 3."] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Specialize with `true`:"] # ! [doc = "  │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │   1. `[true]` // now exploring irrelevant cases"] # ! [doc = "  │ │ │ │   2. `[_]`    // now exploring irrelevant cases"] # ! [doc = "  │ │ │ │   3. `[_]`    // now exploring irrelevant cases"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ The current case is irrelevant for all rows: we backtrack immediately."] # ! [doc = "  │ │ ├─┘"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Specialize with `false`:"] # ! [doc = "  │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │   1. `[true]`"] # ! [doc = "  │ │ │ │   3. `[_]`    // now exploring irrelevant cases"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ Specialize with `true`:"] # ! [doc = "  │ │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │ │   1. `[]`"] # ! [doc = "  │ │ │ │ │   3. `[]`    // now exploring irrelevant cases"] # ! [doc = "  │ │ │ │ │"] # ! [doc = "  │ │ │ │ │ Row 1 is therefore useful."] # ! [doc = "  │ │ │ ├─┘"] # ! [doc = " <etc...>"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Relevancy allowed us to skip the case `(true, true, _)` entirely. In some cases this pruning can"] # ! [doc = " give drastic speedups. The case this was built for is the following (#118437):"] # ! [doc = ""] # ! [doc = " ```ignore(illustrative)"] # ! [doc = " match foo {"] # ! [doc = "     (true, _, _, _, ..) => 1,"] # ! [doc = "     (_, true, _, _, ..) => 2,"] # ! [doc = "     (_, _, true, _, ..) => 3,"] # ! [doc = "     (_, _, _, true, ..) => 4,"] # ! [doc = "     ..."] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Without considering relevancy, we would explore all 2^n combinations of the `true` and `Missing`"] # ! [doc = " constructors. Relevancy tells us that e.g. `(true, true, false, false, false, ...)` is"] # ! [doc = " irrelevant for all the rows. This allows us to skip all cases with more than one `true`"] # ! [doc = " constructor, changing the runtime from exponential to linear."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " ## Relevancy and exhaustiveness"] # ! [doc = ""] # ! [doc = " For exhaustiveness, we do something slightly different w.r.t relevancy: we do not report"] # ! [doc = " witnesses of non-exhaustiveness that are irrelevant for the virtual wildcard row. For example,"] # ! [doc = " in:"] # ! [doc = ""] # ! [doc = " ```ignore(illustrative)"] # ! [doc = " match foo {"] # ! [doc = "     (true, true) => {}"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " we only report `(false, _)` as missing. This was a deliberate choice made early in the"] # ! [doc = " development of rust, for diagnostic and performance purposes. As showed in the previous section,"] # ! [doc = " ignoring irrelevant cases preserves usefulness, so this choice still correctly computes whether"] # ! [doc = " a match is exhaustive."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Or-patterns"] # ! [doc = ""] # ! [doc = " What we have described so far works well if there are no or-patterns. To handle them, if the"] # ! [doc = " first pattern of any row in the matrix is an or-pattern, we expand it by duplicating the rest of"] # ! [doc = " the row as necessary. For code reuse, this is implemented as \"specializing with the `Or`"] # ! [doc = " constructor\"."] # ! [doc = ""] # ! [doc = " This makes usefulness tracking subtle, because we also want to compute whether an alternative of"] # ! [doc = " an or-pattern is redundant, e.g. in `Some(_) | Some(0)`. We therefore track usefulness of each"] # ! [doc = " subpattern of the match."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Constants and opaques"] # ! [doc = ""] # ! [doc = " There are two kinds of constants in patterns:"] # ! [doc = ""] # ! [doc = " * literals (`1`, `true`, `\"foo\"`)"] # ! [doc = " * named or inline consts (`FOO`, `const { 5 + 6 }`)"] # ! [doc = ""] # ! [doc = " The latter are converted into the corresponding patterns by a previous phase. For example"] # ! [doc = " `const_to_pat(const { [1, 2, 3] })` becomes an `Array(vec![Const(1), Const(2), Const(3)])`"] # ! [doc = " pattern. This gets problematic when comparing the constant via `==` would behave differently"] # ! [doc = " from matching on the constant converted to a pattern. The situation around this is currently"] # ! [doc = " unclear and the lang team is working on clarifying what we want to do there. In any case, there"] # ! [doc = " are constants we will not turn into patterns. We capture these with `Constructor::Opaque`. These"] # ! [doc = " `Opaque` patterns do not participate in exhaustiveness, specialization or overlap checking."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Usefulness vs reachability, validity, and empty patterns"] # ! [doc = ""] # ! [doc = " This is likely the subtlest aspect of the algorithm. To be fully precise, a match doesn't"] # ! [doc = " operate on a value, it operates on a place. In certain unsafe circumstances, it is possible for"] # ! [doc = " a place to not contain valid data for its type. This has subtle consequences for empty types."] # ! [doc = " Take the following:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " enum Void {}"] # ! [doc = " let x: u8 = 0;"] # ! [doc = " let ptr: *const Void = &x as *const u8 as *const Void;"] # ! [doc = " unsafe {"] # ! [doc = "     match *ptr {"] # ! [doc = "         _ => println!(\"Reachable!\"),"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " In this example, `ptr` is a valid pointer pointing to a place with invalid data. The `_` pattern"] # ! [doc = " does not look at the contents of `*ptr`, so this is ok and the arm is taken. In other words,"] # ! [doc = " despite the place we are inspecting being of type `Void`, there is a reachable arm. If the"] # ! [doc = " arm had a binding however:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " # #[derive(Copy, Clone)]"] # ! [doc = " # enum Void {}"] # ! [doc = " # let x: u8 = 0;"] # ! [doc = " # let ptr: *const Void = &x as *const u8 as *const Void;"] # ! [doc = " # unsafe {"] # ! [doc = " match *ptr {"] # ! [doc = "     _a => println!(\"Unreachable!\"),"] # ! [doc = " }"] # ! [doc = " # }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Here the binding loads the value of type `Void` from the `*ptr` place. In this example, this"] # ! [doc = " causes UB since the data is not valid. In the general case, this asserts validity of the data at"] # ! [doc = " `*ptr`. Either way, this arm will never be taken."] # ! [doc = ""] # ! [doc = " Finally, let's consider the empty match `match *ptr {}`. If we consider this exhaustive, then"] # ! [doc = " having invalid data at `*ptr` is invalid. In other words, the empty match is semantically"] # ! [doc = " equivalent to the `_a => ...` match. In the interest of explicitness, we prefer the case with an"] # ! [doc = " arm, hence we won't tell the user to remove the `_a` arm. In other words, the `_a` arm is"] # ! [doc = " unreachable yet not redundant. This is why we lint on redundant arms rather than unreachable"] # ! [doc = " arms, despite the fact that the lint says \"unreachable\"."] # ! [doc = ""] # ! [doc = " These considerations only affects certain places, namely those that can contain non-valid data"] # ! [doc = " without UB. These are: pointer dereferences, reference dereferences, and union field accesses."] # ! [doc = " We track in the algorithm whether a given place is known to contain valid data. This is done"] # ! [doc = " first by inspecting the scrutinee syntactically (which gives us `cx.known_valid_scrutinee`), and"] # ! [doc = " then by tracking validity of each column of the matrix (which correspond to places) as we"] # ! [doc = " recurse into subpatterns. That second part is done through [`PlaceValidity`], most notably"] # ! [doc = " [`PlaceValidity::specialize`]."] # ! [doc = ""] # ! [doc = " Having said all that, we don't fully follow what's been presented in this section. For"] # ! [doc = " backwards-compatibility, we ignore place validity when checking whether a pattern is required"] # ! [doc = " for exhaustiveness in two cases: when the `exhaustive_patterns` feature gate is on, or when the"] # ! [doc = " match scrutinee itself has type `!` or `EmptyEnum`. I (Nadrieril) hope to deprecate this"] # ! [doc = " exception."] # ! [doc = ""] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Full example"] # ! [doc = ""] # ! [doc = " We illustrate a full run of the algorithm on the following match."] # ! [doc = ""] # ! [doc = " ```compile_fail,E0004"] # ! [doc = " # struct Pair(Option<u32>, bool);"] # ! [doc = " # fn foo(x: Pair) -> u32 {"] # ! [doc = " match x {"] # ! [doc = "     Pair(Some(0), _) => 1,"] # ! [doc = "     Pair(_, false) => 2,"] # ! [doc = "     Pair(Some(0), false) => 3,"] # ! [doc = " }"] # ! [doc = " # }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " We keep track of the original row for illustration purposes, this is not what the algorithm"] # ! [doc = " actually does (it tracks usefulness as a boolean on each row)."] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = "  ┐ Patterns:"] # ! [doc = "  │   1. `[Pair(Some(0), _)]`"] # ! [doc = "  │   2. `[Pair(_, false)]`"] # ! [doc = "  │   3. `[Pair(Some(0), false)]`"] # ! [doc = "  │"] # ! [doc = "  │ Specialize with `Pair`:"] # ! [doc = "  ├─┐ Patterns:"] # ! [doc = "  │ │   1. `[Some(0), _]`"] # ! [doc = "  │ │   2. `[_, false]`"] # ! [doc = "  │ │   3. `[Some(0), false]`"] # ! [doc = "  │ │"] # ! [doc = "  │ │ Specialize with `Some`:"] # ! [doc = "  │ ├─┐ Patterns:"] # ! [doc = "  │ │ │   1. `[0, _]`"] # ! [doc = "  │ │ │   2. `[_, false]`"] # ! [doc = "  │ │ │   3. `[0, false]`"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Specialize with `0`:"] # ! [doc = "  │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │   1. `[_]`"] # ! [doc = "  │ │ │ │   3. `[false]`"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ Specialize with `true`:"] # ! [doc = "  │ │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │ │   1. `[]`"] # ! [doc = "  │ │ │ │ │"] # ! [doc = "  │ │ │ │ │ We note arm 1 is useful (by `Pair(Some(0), true)`)."] # ! [doc = "  │ │ │ ├─┘"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ Specialize with `false`:"] # ! [doc = "  │ │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │ │   1. `[]`"] # ! [doc = "  │ │ │ │ │   3. `[]`"] # ! [doc = "  │ │ │ │ │"] # ! [doc = "  │ │ │ │ │ We note arm 1 is useful (by `Pair(Some(0), false)`)."] # ! [doc = "  │ │ │ ├─┘"] # ! [doc = "  │ │ ├─┘"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Specialize with `1..`:"] # ! [doc = "  │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │   2. `[false]`"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ Specialize with `true`:"] # ! [doc = "  │ │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │ │   // no rows left"] # ! [doc = "  │ │ │ │ │"] # ! [doc = "  │ │ │ │ │ We have found an unmatched value (`Pair(Some(1..), true)`)! This gives us a witness."] # ! [doc = "  │ │ │ │ │ New witnesses:"] # ! [doc = "  │ │ │ │ │   `[]`"] # ! [doc = "  │ │ │ ├─┘"] # ! [doc = "  │ │ │ │ Unspecialize new witnesses with `true`:"] # ! [doc = "  │ │ │ │   `[true]`"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ Specialize with `false`:"] # ! [doc = "  │ │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │ │   2. `[]`"] # ! [doc = "  │ │ │ │ │"] # ! [doc = "  │ │ │ │ │ We note arm 2 is useful (by `Pair(Some(1..), false)`)."] # ! [doc = "  │ │ │ ├─┘"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ Total witnesses for `1..`:"] # ! [doc = "  │ │ │ │   `[true]`"] # ! [doc = "  │ │ ├─┘"] # ! [doc = "  │ │ │ Unspecialize new witnesses with `1..`:"] # ! [doc = "  │ │ │   `[1.., true]`"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Total witnesses for `Some`:"] # ! [doc = "  │ │ │   `[1.., true]`"] # ! [doc = "  │ ├─┘"] # ! [doc = "  │ │ Unspecialize new witnesses with `Some`:"] # ! [doc = "  │ │   `[Some(1..), true]`"] # ! [doc = "  │ │"] # ! [doc = "  │ │ Specialize with `None`:"] # ! [doc = "  │ ├─┐ Patterns:"] # ! [doc = "  │ │ │   2. `[false]`"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Specialize with `true`:"] # ! [doc = "  │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │   // no rows left"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ We have found an unmatched value (`Pair(None, true)`)! This gives us a witness."] # ! [doc = "  │ │ │ │ New witnesses:"] # ! [doc = "  │ │ │ │   `[]`"] # ! [doc = "  │ │ ├─┘"] # ! [doc = "  │ │ │ Unspecialize new witnesses with `true`:"] # ! [doc = "  │ │ │   `[true]`"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Specialize with `false`:"] # ! [doc = "  │ │ ├─┐ Patterns:"] # ! [doc = "  │ │ │ │   2. `[]`"] # ! [doc = "  │ │ │ │"] # ! [doc = "  │ │ │ │ We note arm 2 is useful (by `Pair(None, false)`)."] # ! [doc = "  │ │ ├─┘"] # ! [doc = "  │ │ │"] # ! [doc = "  │ │ │ Total witnesses for `None`:"] # ! [doc = "  │ │ │   `[true]`"] # ! [doc = "  │ ├─┘"] # ! [doc = "  │ │ Unspecialize new witnesses with `None`:"] # ! [doc = "  │ │   `[None, true]`"] # ! [doc = "  │ │"] # ! [doc = "  │ │ Total witnesses for `Pair`:"] # ! [doc = "  │ │   `[Some(1..), true]`"] # ! [doc = "  │ │   `[None, true]`"] # ! [doc = "  ├─┘"] # ! [doc = "  │ Unspecialize new witnesses with `Pair`:"] # ! [doc = "  │   `[Pair(Some(1..), true)]`"] # ! [doc = "  │   `[Pair(None, true)]`"] # ! [doc = "  │"] # ! [doc = "  │ Final witnesses:"] # ! [doc = "  │   `[Pair(Some(1..), true)]`"] # ! [doc = "  │   `[Pair(None, true)]`"] # ! [doc = "  ┘"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " We conclude:"] # ! [doc = " - Arm 3 is redundant (it was never marked as useful);"] # ! [doc = " - The match is not exhaustive;"] # ! [doc = " - Adding arms with `Pair(Some(1..), true)` and `Pair(None, true)` would make the match exhaustive."] # ! [doc = ""] # ! [doc = " Note that when we're deep in the algorithm, we don't know what specialization steps got us here."] # ! [doc = " We can only figure out what our witnesses correspond to by unspecializing back up the stack."] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Tests"] # ! [doc = ""] # ! [doc = " Note: tests specific to this file can be found in:"] # ! [doc = ""] # ! [doc = "   - `ui/pattern/usefulness`"] # ! [doc = "   - `ui/or-patterns`"] # ! [doc = "   - `ui/consts/const_in_pattern`"] # ! [doc = "   - `ui/rfc-2008-non-exhaustive`"] # ! [doc = "   - `ui/half-open-range-patterns`"] # ! [doc = "   - `ui/pattern/deref-patterns`"] # ! [doc = "   - probably many others"] # ! [doc = ""] # ! [doc = " I (Nadrieril) prefer to put new tests in `ui/pattern/usefulness` unless there's a specific"] # ! [doc = " reason not to, for example if they crucially depend on a particular feature like `or_patterns`."] use split_decls_genesis :: ourprelude :: * ; use std :: fmt ; #[cfg (feature = "rustc")] use rustc_data_structures :: stack :: ensure_sufficient_stack ; use rustc_hash :: { FxHashMap , FxHashSet } ; use rustc_index :: bit_set :: DenseBitSet ; use smallvec :: { SmallVec , smallvec } ; use tracing :: { debug , instrument } ; use self :: PlaceValidity :: * ; use crate :: constructor :: { Constructor , ConstructorSet , IntRange } ; use crate :: pat :: { DeconstructedPat , PatId , PatOrWild , WitnessPat } ; use crate :: { MatchArm , PatCx , PrivateUninhabitedField , checks } ; #[cfg (not (feature = "rustc"))] pub fn ensure_sufficient_stack < R > (f : impl FnOnce () -> R) -> R { f () } #[doc = " A pattern is a \"branch\" if it is the immediate child of an or-pattern, or if it is the whole"] #[doc = " pattern of a match arm. These are the patterns that can be meaningfully considered \"redundant\","] #[doc = " since e.g. `0` in `(0, 1)` cannot be redundant on its own."] #[doc = ""] #[doc = " We track for each branch pattern whether it is useful, and if not why."] struct BranchPatUsefulness < 'p , Cx : PatCx > { #[doc = " Whether this pattern is useful."] useful : bool , #[doc = " A set of patterns that:"] #[doc = " - come before this one in the match;"] #[doc = " - intersect this one;"] #[doc = " - at the end of the algorithm, if `!self.useful`, their union covers this pattern."] covered_by : FxHashSet < & 'p DeconstructedPat < Cx > > , } impl < 'p , Cx : PatCx > BranchPatUsefulness < 'p , Cx > { #[doc = " Update `self` with the usefulness information found in `row`."] fn update (& mut self , row : & MatrixRow < 'p , Cx > , matrix : & Matrix < 'p , Cx >) { self . useful |= row . useful ; for row_id in row . intersects_at_least . iter () { let row = & matrix . rows [row_id] ; if row . useful && ! row . is_under_guard { if let PatOrWild :: Pat (intersecting) = row . head () { self . covered_by . insert (intersecting) ; } } } } #[doc = " Check whether this pattern is redundant, and if so explain why."] fn is_redundant (& self) -> Option < RedundancyExplanation < 'p , Cx > > { if self . useful { None } else { #[cfg_attr (feature = "rustc" , allow (rustc :: potential_query_instability))] let mut covered_by : Vec < _ > = self . covered_by . iter () . copied () . collect () ; covered_by . sort_by_key (| pat | pat . uid) ; Some (RedundancyExplanation { covered_by }) } } } impl < 'p , Cx : PatCx > Default for BranchPatUsefulness < 'p , Cx > { fn default () -> Self { Self { useful : Default :: default () , covered_by : Default :: default () } } } #[doc = " Context that provides information for usefulness checking."] struct UsefulnessCtxt < 'a , 'p , Cx : PatCx > { #[doc = " The context for type information."] tycx : & 'a Cx , #[doc = " Track information about the usefulness of branch patterns (see definition of \"branch"] #[doc = " pattern\" at [`BranchPatUsefulness`])."] branch_usefulness : FxHashMap < PatId , BranchPatUsefulness < 'p , Cx > > , complexity_limit : usize , complexity_level : usize , } impl < 'a , 'p , Cx : PatCx > UsefulnessCtxt < 'a , 'p , Cx > { fn increase_complexity_level (& mut self , complexity_add : usize) -> Result < () , Cx :: Error > { self . complexity_level += complexity_add ; if self . complexity_level <= self . complexity_limit { Ok (()) } else { self . tycx . complexity_exceeded () } } } #[doc = " Context that provides information local to a place under investigation."] struct PlaceCtxt < 'a , Cx : PatCx > { cx : & 'a Cx , #[doc = " Type of the place under investigation."] ty : & 'a Cx :: Ty , } impl < 'a , Cx : PatCx > Copy for PlaceCtxt < 'a , Cx > { } impl < 'a , Cx : PatCx > Clone for PlaceCtxt < 'a , Cx > { fn clone (& self) -> Self { Self { cx : self . cx , ty : self . ty } } } impl < 'a , Cx : PatCx > fmt :: Debug for PlaceCtxt < 'a , Cx > { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { fmt . debug_struct ("PlaceCtxt") . field ("ty" , self . ty) . finish () } } impl < 'a , Cx : PatCx > PlaceCtxt < 'a , Cx > { fn ctor_arity (& self , ctor : & Constructor < Cx >) -> usize { self . cx . ctor_arity (ctor , self . ty) } fn wild_from_ctor (& self , ctor : Constructor < Cx >) -> WitnessPat < Cx > { WitnessPat :: wild_from_ctor (self . cx , ctor , self . ty . clone ()) } } #[doc = " Track whether a given place (aka column) is known to contain a valid value or not."] #[derive (Debug , Copy , Clone , PartialEq , Eq)] pub enum PlaceValidity { ValidOnly , MaybeInvalid , } impl PlaceValidity { pub fn from_bool (is_valid_only : bool) -> Self { if is_valid_only { ValidOnly } else { MaybeInvalid } } fn is_known_valid (self) -> bool { matches ! (self , ValidOnly) } #[doc = " If the place has validity given by `self` and we read that the value at the place has"] #[doc = " constructor `ctor`, this computes what we can assume about the validity of the constructor"] #[doc = " fields."] #[doc = ""] #[doc = " Pending further opsem decisions, the current behavior is: validity is preserved, except"] #[doc = " inside `&` and union fields where validity is reset to `MaybeInvalid`."] fn specialize < Cx : PatCx > (self , ctor : & Constructor < Cx >) -> Self { if matches ! (ctor , Constructor :: Ref | Constructor :: DerefPattern (_) | Constructor :: UnionField) { MaybeInvalid } else { self } } } impl fmt :: Display for PlaceValidity { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { let s = match self { ValidOnly => "✓" , MaybeInvalid => "?" , } ; write ! (f , "{s}") } } #[doc = " Data about a place under investigation. Its methods contain a lot of the logic used to analyze"] #[doc = " the constructors in the matrix."] struct PlaceInfo < Cx : PatCx > { #[doc = " The type of the place."] ty : Cx :: Ty , #[doc = " Whether the place is a private uninhabited field. If so we skip this field during analysis"] #[doc = " so that we don't observe its emptiness."] private_uninhabited : bool , #[doc = " Whether the place is known to contain valid data."] validity : PlaceValidity , #[doc = " Whether the place is the scrutinee itself or a subplace of it."] is_scrutinee : bool , } impl < Cx : PatCx > PlaceInfo < Cx > { #[doc = " Given a constructor for the current place, we return one `PlaceInfo` for each field of the"] #[doc = " constructor."] fn specialize (& self , cx : & Cx , ctor : & Constructor < Cx > ,) -> impl Iterator < Item = Self > + ExactSizeIterator { let ctor_sub_tys = cx . ctor_sub_tys (ctor , & self . ty) ; let ctor_sub_validity = self . validity . specialize (ctor) ; ctor_sub_tys . map (move | (ty , PrivateUninhabitedField (private_uninhabited)) | PlaceInfo { ty , private_uninhabited , validity : ctor_sub_validity , is_scrutinee : false , }) } #[doc = " This analyzes a column of constructors corresponding to the current place. It returns a pair"] #[doc = " `(split_ctors, missing_ctors)`."] #[doc = ""] #[doc = " `split_ctors` is a splitted list of constructors that cover the whole type. This will be"] #[doc = " used to specialize the matrix."] #[doc = ""] #[doc = " `missing_ctors` is a list of the constructors not found in the column, for reporting"] #[doc = " purposes."] fn split_column_ctors < 'a > (& self , cx : & Cx , ctors : impl Iterator < Item = & 'a Constructor < Cx > > + Clone ,) -> Result < (SmallVec < [Constructor < Cx > ; 1] > , Vec < Constructor < Cx > >) , Cx :: Error > where Cx : 'a , { debug ! (? self . ty) ; if self . private_uninhabited { return Ok ((smallvec ! [Constructor :: PrivateUninhabited] , vec ! [])) ; } if ctors . clone () . any (| c | matches ! (c , Constructor :: Or)) { return Ok ((smallvec ! [Constructor :: Or] , vec ! [])) ; } let ctors_for_ty = cx . ctors_for_ty (& self . ty) ? ; debug ! (? ctors_for_ty) ; let is_toplevel_exception = self . is_scrutinee && matches ! (ctors_for_ty , ConstructorSet :: NoConstructors) ; let empty_arms_are_unreachable = self . validity . is_known_valid () && (is_toplevel_exception || cx . is_exhaustive_patterns_feature_on ()) ; let can_omit_empty_arms = self . validity . is_known_valid () || is_toplevel_exception || cx . is_exhaustive_patterns_feature_on () ; let mut split_set = ctors_for_ty . split (ctors) ; debug ! (? split_set) ; let all_missing = split_set . present . is_empty () ; let mut split_ctors = split_set . present ; if ! (split_set . missing . is_empty () && (split_set . missing_empty . is_empty () || empty_arms_are_unreachable)) { split_ctors . push (Constructor :: Missing) ; } let mut missing_ctors = split_set . missing ; if ! can_omit_empty_arms { missing_ctors . append (& mut split_set . missing_empty) ; } let report_individual_missing_ctors = self . is_scrutinee || ! all_missing ; if ! missing_ctors . is_empty () && ! report_individual_missing_ctors { missing_ctors = vec ! [Constructor :: Wildcard] ; } else if missing_ctors . iter () . any (| c | c . is_non_exhaustive ()) && ! cx . exhaustive_witnesses () { missing_ctors = vec ! [Constructor :: NonExhaustive] ; } Ok ((split_ctors , missing_ctors)) } } impl < Cx : PatCx > Clone for PlaceInfo < Cx > { fn clone (& self) -> Self { Self { ty : self . ty . clone () , private_uninhabited : self . private_uninhabited , validity : self . validity , is_scrutinee : self . is_scrutinee , } } } #[doc = " Represents a pattern-tuple under investigation."] struct PatStack < 'p , Cx : PatCx > { pats : SmallVec < [PatOrWild < 'p , Cx > ; 2] > , #[doc = " Sometimes we know that as far as this row is concerned, the current case is already handled"] #[doc = " by a different, more general, case. When the case is irrelevant for all rows this allows us"] #[doc = " to skip a case entirely. This is purely an optimization. See at the top for details."] relevant : bool , } impl < 'p , Cx : PatCx > Clone for PatStack < 'p , Cx > { fn clone (& self) -> Self { Self { pats : self . pats . clone () , relevant : self . relevant } } } impl < 'p , Cx : PatCx > PatStack < 'p , Cx > { fn from_pattern (pat : & 'p DeconstructedPat < Cx >) -> Self { PatStack { pats : smallvec ! [PatOrWild :: Pat (pat)] , relevant : true } } fn len (& self) -> usize { self . pats . len () } fn head (& self) -> PatOrWild < 'p , Cx > { self . pats [0] } fn iter (& self) -> impl Iterator < Item = PatOrWild < 'p , Cx > > { self . pats . iter () . copied () } fn expand_or_pat (& self) -> impl Iterator < Item = PatStack < 'p , Cx > > { self . head () . expand_or_pat () . into_iter () . map (move | pat | { let mut new = self . clone () ; new . pats [0] = pat ; new }) } #[doc = " This computes `specialize(ctor, self)`. See top of the file for explanations."] #[doc = " Only call if `ctor.is_covered_by(self.head().ctor())` is true."] fn pop_head_constructor (& self , cx : & Cx , ctor : & Constructor < Cx > , ctor_arity : usize , ctor_is_relevant : bool ,) -> Result < PatStack < 'p , Cx > , Cx :: Error > { let head_pat = self . head () ; if head_pat . as_pat () . is_some_and (| pat | pat . arity () > ctor_arity) { return Err (cx . bug (format_args ! ("uncaught type error: pattern {:?} has inconsistent arity (expected arity <= {ctor_arity})" , head_pat . as_pat () . unwrap ()))) ; } let mut new_pats = head_pat . specialize (ctor , ctor_arity) ; new_pats . extend_from_slice (& self . pats [1 ..]) ; let ctor_is_relevant = ! matches ! (self . head () . ctor () , Constructor :: Wildcard) || ctor_is_relevant ; Ok (PatStack { pats : new_pats , relevant : self . relevant && ctor_is_relevant }) } } impl < 'p , Cx : PatCx > fmt :: Debug for PatStack < 'p , Cx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (f , "+") ? ; for pat in self . iter () { write ! (f , " {pat:?} +") ? ; } Ok (()) } } #[doc = " A row of the matrix."] #[derive (Clone)] struct MatrixRow < 'p , Cx : PatCx > { pats : PatStack < 'p , Cx > , #[doc = " Whether the original arm had a guard. This is inherited when specializing."] is_under_guard : bool , #[doc = " When we specialize, we remember which row of the original matrix produced a given row of the"] #[doc = " specialized matrix. When we unspecialize, we use this to propagate usefulness back up the"] #[doc = " callstack. On creation, this stores the index of the original match arm."] parent_row : usize , #[doc = " False when the matrix is just built. This is set to `true` by"] #[doc = " [`compute_exhaustiveness_and_usefulness`] if the arm is found to be useful."] #[doc = " This is reset to `false` when specializing."] useful : bool , #[doc = " Tracks some rows above this one that have an intersection with this one, i.e. such that"] #[doc = " there is a value that matches both rows."] #[doc = " Because of relevancy we may miss some intersections. The intersections we do find are"] #[doc = " correct. In other words, this is an underapproximation of the real set of intersections."] #[doc = ""] #[doc = " For example:"] #[doc = " ```rust,ignore(illustrative)"] #[doc = " match ... {"] #[doc = "     (true, _, _) => {} // `intersects_at_least = []`"] #[doc = "     (_, true, 0..=10) => {} // `intersects_at_least = []`"] #[doc = "     (_, true, 5..15) => {} // `intersects_at_least = [1]`"] #[doc = " }"] #[doc = " ```"] #[doc = " Here the `(true, true)` case is irrelevant. Since we skip it, we will not detect that row 0"] #[doc = " intersects rows 1 and 2."] intersects_at_least : DenseBitSet < usize > , #[doc = " Whether the head pattern is a branch (see definition of \"branch pattern\" at"] #[doc = " [`BranchPatUsefulness`])"] head_is_branch : bool , } impl < 'p , Cx : PatCx > MatrixRow < 'p , Cx > { fn new (arm : & MatchArm < 'p , Cx > , arm_id : usize) -> Self { MatrixRow { pats : PatStack :: from_pattern (arm . pat) , parent_row : arm_id , is_under_guard : arm . has_guard , useful : false , intersects_at_least : DenseBitSet :: new_empty (0) , head_is_branch : true , } } fn len (& self) -> usize { self . pats . len () } fn head (& self) -> PatOrWild < 'p , Cx > { self . pats . head () } fn iter (& self) -> impl Iterator < Item = PatOrWild < 'p , Cx > > { self . pats . iter () } fn expand_or_pat (& self , parent_row : usize) -> impl Iterator < Item = MatrixRow < 'p , Cx > > { let is_or_pat = self . pats . head () . is_or_pat () ; self . pats . expand_or_pat () . map (move | patstack | MatrixRow { pats : patstack , parent_row , is_under_guard : self . is_under_guard , useful : false , intersects_at_least : DenseBitSet :: new_empty (0) , head_is_branch : is_or_pat , }) } #[doc = " This computes `specialize(ctor, self)`. See top of the file for explanations."] #[doc = " Only call if `ctor.is_covered_by(self.head().ctor())` is true."] fn pop_head_constructor (& self , cx : & Cx , ctor : & Constructor < Cx > , ctor_arity : usize , ctor_is_relevant : bool , parent_row : usize ,) -> Result < MatrixRow < 'p , Cx > , Cx :: Error > { Ok (MatrixRow { pats : self . pats . pop_head_constructor (cx , ctor , ctor_arity , ctor_is_relevant) ? , parent_row , is_under_guard : self . is_under_guard , useful : false , intersects_at_least : DenseBitSet :: new_empty (0) , head_is_branch : false , }) } } impl < 'p , Cx : PatCx > fmt :: Debug for MatrixRow < 'p , Cx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . pats . fmt (f) } } #[doc = " A 2D matrix. Represents a list of pattern-tuples under investigation."] #[doc = ""] #[doc = " Invariant: each row must have the same length, and each column must have the same type."] #[doc = ""] #[doc = " Invariant: the first column must not contain or-patterns. This is handled by"] #[doc = " [`Matrix::push`]."] #[doc = ""] #[doc = " In fact each column corresponds to a place inside the scrutinee of the match. E.g. after"] #[doc = " specializing `(,)` and `Some` on a pattern of type `(Option<u32>, bool)`, the first column of"] #[doc = " the matrix will correspond to `scrutinee.0.Some.0` and the second column to `scrutinee.1`."] #[derive (Clone)] struct Matrix < 'p , Cx : PatCx > { #[doc = " Vector of rows. The rows must form a rectangular 2D array. Moreover, all the patterns of"] #[doc = " each column must have the same type. Each column corresponds to a place within the"] #[doc = " scrutinee."] rows : Vec < MatrixRow < 'p , Cx > > , #[doc = " Track info about each place. Each place corresponds to a column in `rows`, and their types"] #[doc = " must match."] place_info : SmallVec < [PlaceInfo < Cx > ; 2] > , #[doc = " Track whether the virtual wildcard row used to compute exhaustiveness is relevant. See top"] #[doc = " of the file for details on relevancy."] wildcard_row_is_relevant : bool , } impl < 'p , Cx : PatCx > Matrix < 'p , Cx > { #[doc = " Pushes a new row to the matrix. Internal method, prefer [`Matrix::new`]."] fn push (& mut self , mut row : MatrixRow < 'p , Cx >) { row . intersects_at_least = DenseBitSet :: new_empty (self . rows . len ()) ; self . rows . push (row) ; } #[doc = " Build a new matrix from an iterator of `MatchArm`s."] fn new (arms : & [MatchArm < 'p , Cx >] , scrut_ty : Cx :: Ty , scrut_validity : PlaceValidity) -> Self { let place_info = PlaceInfo { ty : scrut_ty , private_uninhabited : false , validity : scrut_validity , is_scrutinee : true , } ; let mut matrix = Matrix { rows : Vec :: with_capacity (arms . len ()) , place_info : smallvec ! [place_info] , wildcard_row_is_relevant : true , } ; for (arm_id , arm) in arms . iter () . enumerate () { matrix . push (MatrixRow :: new (arm , arm_id)) ; } matrix } fn head_place (& self) -> Option < & PlaceInfo < Cx > > { self . place_info . first () } fn column_count (& self) -> usize { self . place_info . len () } fn rows (& self ,) -> impl Iterator < Item = & MatrixRow < 'p , Cx > > + Clone + DoubleEndedIterator + ExactSizeIterator { self . rows . iter () } fn rows_mut (& mut self ,) -> impl Iterator < Item = & mut MatrixRow < 'p , Cx > > + DoubleEndedIterator + ExactSizeIterator { self . rows . iter_mut () } #[doc = " Iterate over the first pattern of each row."] fn heads (& self) -> impl Iterator < Item = PatOrWild < 'p , Cx > > + Clone { self . rows () . map (| r | r . head ()) } #[doc = " This computes `specialize(ctor, self)`. See top of the file for explanations."] fn specialize_constructor (& self , pcx : & PlaceCtxt < '_ , Cx > , ctor : & Constructor < Cx > , ctor_is_relevant : bool ,) -> Result < Matrix < 'p , Cx > , Cx :: Error > { if matches ! (ctor , Constructor :: Or) { let mut matrix = Matrix { rows : Vec :: new () , place_info : self . place_info . clone () , wildcard_row_is_relevant : self . wildcard_row_is_relevant , } ; for (i , row) in self . rows () . enumerate () { for new_row in row . expand_or_pat (i) { matrix . push (new_row) ; } } Ok (matrix) } else { let subfield_place_info = self . place_info [0] . specialize (pcx . cx , ctor) ; let arity = subfield_place_info . len () ; let specialized_place_info = subfield_place_info . chain (self . place_info [1 ..] . iter () . cloned ()) . collect () ; let mut matrix = Matrix { rows : Vec :: new () , place_info : specialized_place_info , wildcard_row_is_relevant : self . wildcard_row_is_relevant && ctor_is_relevant , } ; for (i , row) in self . rows () . enumerate () { if ctor . is_covered_by (pcx . cx , row . head () . ctor ()) ? { let new_row = row . pop_head_constructor (pcx . cx , ctor , arity , ctor_is_relevant , i) ? ; matrix . push (new_row) ; } } Ok (matrix) } } #[doc = " Recover row usefulness and intersection information from a processed specialized matrix."] #[doc = " `specialized` must come from `self.specialize_constructor`."] fn unspecialize (& mut self , specialized : Self) { for child_row in specialized . rows () { let parent_row_id = child_row . parent_row ; let parent_row = & mut self . rows [parent_row_id] ; parent_row . useful |= child_row . useful ; for child_intersection in child_row . intersects_at_least . iter () { let parent_intersection = specialized . rows [child_intersection] . parent_row ; if parent_intersection != parent_row_id { parent_row . intersects_at_least . insert (parent_intersection) ; } } } } } #[doc = " Pretty-printer for matrices of patterns, example:"] #[doc = ""] #[doc = " ```text"] #[doc = " + _     + []                +"] #[doc = " + true  + [First]           +"] #[doc = " + true  + [Second(true)]    +"] #[doc = " + false + [_]               +"] #[doc = " + _     + [_, _, tail @ ..] +"] #[doc = " | ✓     | ?                 | // validity"] #[doc = " ```"] impl < 'p , Cx : PatCx > fmt :: Debug for Matrix < 'p , Cx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (f , "\n") ? ; let mut pretty_printed_matrix : Vec < Vec < String > > = self . rows . iter () . map (| row | row . iter () . map (| pat | format ! ("{pat:?}")) . collect ()) . collect () ; pretty_printed_matrix . push (self . place_info . iter () . map (| place | format ! ("{}" , place . validity)) . collect ()) ; let column_count = self . column_count () ; assert ! (self . rows . iter () . all (| row | row . len () == column_count)) ; assert ! (self . place_info . len () == column_count) ; let column_widths : Vec < usize > = (0 .. column_count) . map (| col | pretty_printed_matrix . iter () . map (| row | row [col] . len ()) . max () . unwrap_or (0)) . collect () ; for (row_i , row) in pretty_printed_matrix . into_iter () . enumerate () { let is_validity_row = row_i == self . rows . len () ; let sep = if is_validity_row { "|" } else { "+" } ; write ! (f , "{sep}") ? ; for (column , pat_str) in row . into_iter () . enumerate () { write ! (f , " ") ? ; write ! (f , "{:1$}" , pat_str , column_widths [column]) ? ; write ! (f , " {sep}") ? ; } if is_validity_row { write ! (f , " // validity") ? ; } write ! (f , "\n") ? ; } Ok (()) } } #[doc = " A witness-tuple of non-exhaustiveness for error reporting, represented as a list of patterns (in"] #[doc = " reverse order of construction)."] #[doc = ""] #[doc = " This mirrors `PatStack`: they function similarly, except `PatStack` contains user patterns we"] #[doc = " are inspecting, and `WitnessStack` contains witnesses we are constructing."] #[doc = " FIXME(Nadrieril): use the same order of patterns for both."] #[doc = ""] #[doc = " A `WitnessStack` should have the same types and length as the `PatStack`s we are inspecting"] #[doc = " (except we store the patterns in reverse order). The same way `PatStack` starts with length 1,"] #[doc = " at the end of the algorithm this will have length 1. In the middle of the algorithm, it can"] #[doc = " contain multiple patterns."] #[doc = ""] #[doc = " For example, if we are constructing a witness for the match against"] #[doc = ""] #[doc = " ```compile_fail,E0004"] #[doc = " struct Pair(Option<(u32, u32)>, bool);"] #[doc = " # fn foo(p: Pair) {"] #[doc = " match p {"] #[doc = "    Pair(None, _) => {}"] #[doc = "    Pair(_, false) => {}"] #[doc = " }"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " We'll perform the following steps (among others):"] #[doc = " ```text"] #[doc = " - Start with a matrix representing the match"] #[doc = "     `PatStack(vec![Pair(None, _)])`"] #[doc = "     `PatStack(vec![Pair(_, false)])`"] #[doc = " - Specialize with `Pair`"] #[doc = "     `PatStack(vec![None, _])`"] #[doc = "     `PatStack(vec![_, false])`"] #[doc = " - Specialize with `Some`"] #[doc = "     `PatStack(vec![_, false])`"] #[doc = " - Specialize with `_`"] #[doc = "     `PatStack(vec![false])`"] #[doc = " - Specialize with `true`"] #[doc = "     // no patstacks left"] #[doc = " - This is a non-exhaustive match: we have the empty witness stack as a witness."] #[doc = "     `WitnessStack(vec![])`"] #[doc = " - Apply `true`"] #[doc = "     `WitnessStack(vec![true])`"] #[doc = " - Apply `_`"] #[doc = "     `WitnessStack(vec![true, _])`"] #[doc = " - Apply `Some`"] #[doc = "     `WitnessStack(vec![true, Some(_)])`"] #[doc = " - Apply `Pair`"] #[doc = "     `WitnessStack(vec![Pair(Some(_), true)])`"] #[doc = " ```"] #[doc = ""] #[doc = " The final `Pair(Some(_), true)` is then the resulting witness."] #[doc = ""] #[doc = " See the top of the file for more detailed explanations and examples."] #[derive (Debug)] struct WitnessStack < Cx : PatCx > (Vec < WitnessPat < Cx > >) ; impl < Cx : PatCx > Clone for WitnessStack < Cx > { fn clone (& self) -> Self { Self (self . 0 . clone ()) } } impl < Cx : PatCx > WitnessStack < Cx > { #[doc = " Asserts that the witness contains a single pattern, and returns it."] fn single_pattern (self) -> WitnessPat < Cx > { assert_eq ! (self . 0 . len () , 1) ; self . 0 . into_iter () . next () . unwrap () } #[doc = " Reverses specialization by the `Missing` constructor by pushing a whole new pattern."] fn push_pattern (& mut self , pat : WitnessPat < Cx >) { self . 0 . push (pat) ; } #[doc = " Reverses specialization. Given a witness obtained after specialization, this constructs a"] #[doc = " new witness valid for before specialization. See the section on `unspecialize` at the top of"] #[doc = " the file."] #[doc = ""] #[doc = " Examples:"] #[doc = " ```text"] #[doc = " ctor: tuple of 2 elements"] #[doc = " pats: [false, \"foo\", _, true]"] #[doc = " result: [(false, \"foo\"), _, true]"] #[doc = ""] #[doc = " ctor: Enum::Variant { a: (bool, &'static str), b: usize}"] #[doc = " pats: [(false, \"foo\"), _, true]"] #[doc = " result: [Enum::Variant { a: (false, \"foo\"), b: _ }, true]"] #[doc = " ```"] fn apply_constructor (mut self , pcx : & PlaceCtxt < '_ , Cx > , ctor : & Constructor < Cx > ,) -> SmallVec < [Self ; 1] > { let len = self . 0 . len () ; let arity = pcx . ctor_arity (ctor) ; let fields : Vec < _ > = self . 0 . drain ((len - arity) ..) . rev () . collect () ; if matches ! (ctor , Constructor :: UnionField) && fields . iter () . filter (| p | ! matches ! (p . ctor () , Constructor :: Wildcard)) . count () >= 2 { self . 0 . push (WitnessPat :: wild_from_ctor (pcx . cx , ctor . clone () , pcx . ty . clone ())) ; fields . into_iter () . enumerate () . filter (| (_ , p) | ! matches ! (p . ctor () , Constructor :: Wildcard)) . map (| (i , p) | { let mut ret = self . clone () ; ret . 0 . last_mut () . unwrap () . fields [i] = p ; ret }) . collect () } else { self . 0 . push (WitnessPat :: new (ctor . clone () , fields , pcx . ty . clone ())) ; smallvec ! [self] } } } #[doc = " Represents a set of pattern-tuples that are witnesses of non-exhaustiveness for error"] #[doc = " reporting. This has similar invariants as `Matrix` does."] #[doc = ""] #[doc = " The `WitnessMatrix` returned by [`compute_exhaustiveness_and_usefulness`] obeys the invariant"] #[doc = " that the union of the input `Matrix` and the output `WitnessMatrix` together matches the type"] #[doc = " exhaustively."] #[doc = ""] #[doc = " Just as the `Matrix` starts with a single column, by the end of the algorithm, this has a single"] #[doc = " column, which contains the patterns that are missing for the match to be exhaustive."] #[derive (Debug)] struct WitnessMatrix < Cx : PatCx > (Vec < WitnessStack < Cx > >) ; impl < Cx : PatCx > Clone for WitnessMatrix < Cx > { fn clone (& self) -> Self { Self (self . 0 . clone ()) } } impl < Cx : PatCx > WitnessMatrix < Cx > { #[doc = " New matrix with no witnesses."] fn empty () -> Self { WitnessMatrix (Vec :: new ()) } #[doc = " New matrix with one `()` witness, i.e. with no columns."] fn unit_witness () -> Self { WitnessMatrix (vec ! [WitnessStack (Vec :: new ())]) } #[doc = " Whether this has any witnesses."] fn is_empty (& self) -> bool { self . 0 . is_empty () } #[doc = " Asserts that there is a single column and returns the patterns in it."] fn single_column (self) -> Vec < WitnessPat < Cx > > { self . 0 . into_iter () . map (| w | w . single_pattern ()) . collect () } #[doc = " Reverses specialization by the `Missing` constructor by pushing a whole new pattern."] fn push_pattern (& mut self , pat : WitnessPat < Cx >) { for witness in self . 0 . iter_mut () { witness . push_pattern (pat . clone ()) } } #[doc = " Reverses specialization by `ctor`. See the section on `unspecialize` at the top of the file."] fn apply_constructor (& mut self , pcx : & PlaceCtxt < '_ , Cx > , missing_ctors : & [Constructor < Cx >] , ctor : & Constructor < Cx > ,) { if self . is_empty () || matches ! (ctor , Constructor :: Or) { return ; } if matches ! (ctor , Constructor :: Missing) { let mut ret = Self :: empty () ; for ctor in missing_ctors { let pat = pcx . wild_from_ctor (ctor . clone ()) ; let mut wit_matrix = self . clone () ; wit_matrix . push_pattern (pat) ; ret . extend (wit_matrix) ; } * self = ret ; } else { for witness in std :: mem :: take (& mut self . 0) { self . 0 . extend (witness . apply_constructor (pcx , ctor)) ; } } } #[doc = " Merges the witnesses of two matrices. Their column types must match."] fn extend (& mut self , other : Self) { self . 0 . extend (other . 0) } } #[doc = " Collect ranges that overlap like `lo..=overlap`/`overlap..=hi`. Must be called during"] #[doc = " exhaustiveness checking, if we find a singleton range after constructor splitting. This reuses"] #[doc = " row intersection information to only detect ranges that truly overlap."] #[doc = ""] #[doc = " If two ranges overlapped, the split set will contain their intersection as a singleton."] #[doc = " Specialization will then select rows that match the overlap, and exhaustiveness will compute"] #[doc = " which rows have an intersection that includes the overlap. That gives us all the info we need to"] #[doc = " compute overlapping ranges without false positives."] #[doc = ""] #[doc = " We can however get false negatives because exhaustiveness does not explore all cases. See the"] #[doc = " section on relevancy at the top of the file."] fn collect_overlapping_range_endpoints < 'p , Cx : PatCx > (cx : & Cx , overlap_range : IntRange , matrix : & Matrix < 'p , Cx > , specialized_matrix : & Matrix < 'p , Cx > ,) { let overlap = overlap_range . lo ; let mut prefixes : SmallVec < [_ ; 1] > = Default :: default () ; let mut suffixes : SmallVec < [_ ; 1] > = Default :: default () ; for (child_row_id , child_row) in specialized_matrix . rows () . enumerate () { let PatOrWild :: Pat (pat) = matrix . rows [child_row . parent_row] . head () else { continue } ; let Constructor :: IntRange (this_range) = pat . ctor () else { continue } ; if this_range . is_singleton () { continue ; } if this_range . lo == overlap { if ! prefixes . is_empty () { let overlaps_with : Vec < _ > = prefixes . iter () . filter (| & & (other_child_row_id , _) | { child_row . intersects_at_least . contains (other_child_row_id) }) . map (| & (_ , pat) | pat) . collect () ; if ! overlaps_with . is_empty () { cx . lint_overlapping_range_endpoints (pat , overlap_range , & overlaps_with) ; } } suffixes . push ((child_row_id , pat)) } else if Some (this_range . hi) == overlap . plus_one () { if ! suffixes . is_empty () { let overlaps_with : Vec < _ > = suffixes . iter () . filter (| & & (other_child_row_id , _) | { child_row . intersects_at_least . contains (other_child_row_id) }) . map (| & (_ , pat) | pat) . collect () ; if ! overlaps_with . is_empty () { cx . lint_overlapping_range_endpoints (pat , overlap_range , & overlaps_with) ; } } prefixes . push ((child_row_id , pat)) } } } #[doc = " Collect ranges that have a singleton gap between them."] fn collect_non_contiguous_range_endpoints < 'p , Cx : PatCx > (cx : & Cx , gap_range : & IntRange , matrix : & Matrix < 'p , Cx > ,) { let gap = gap_range . lo ; let mut onebefore : SmallVec < [_ ; 1] > = Default :: default () ; let mut oneafter : SmallVec < [_ ; 1] > = Default :: default () ; for pat in matrix . heads () { let PatOrWild :: Pat (pat) = pat else { continue } ; let Constructor :: IntRange (this_range) = pat . ctor () else { continue } ; if gap == this_range . hi { onebefore . push (pat) } else if gap . plus_one () == Some (this_range . lo) { oneafter . push (pat) } } for pat_before in onebefore { cx . lint_non_contiguous_range_endpoints (pat_before , * gap_range , oneafter . as_slice ()) ; } } #[doc = " The core of the algorithm."] #[doc = ""] #[doc = " This recursively computes witnesses of the non-exhaustiveness of `matrix` (if any). Also tracks"] #[doc = " usefulness of each row in the matrix (in `row.useful`). We track usefulness of subpatterns in"] #[doc = " `mcx.branch_usefulness`."] #[doc = ""] #[doc = " The input `Matrix` and the output `WitnessMatrix` together match the type exhaustively."] #[doc = ""] #[doc = " The key steps are:"] #[doc = " - specialization, where we dig into the rows that have a specific constructor and call ourselves"] #[doc = "     recursively;"] #[doc = " - unspecialization, where we lift the results from the previous step into results for this step"] #[doc = "     (using `apply_constructor` and by updating `row.useful` for each parent row)."] #[doc = " This is all explained at the top of the file."] #[instrument (level = "debug" , skip (mcx) , ret)] fn compute_exhaustiveness_and_usefulness < 'a , 'p , Cx : PatCx > (mcx : & mut UsefulnessCtxt < 'a , 'p , Cx > , matrix : & mut Matrix < 'p , Cx > ,) -> Result < WitnessMatrix < Cx > , Cx :: Error > { debug_assert ! (matrix . rows () . all (| r | r . len () == matrix . column_count ())) ; if ! matrix . wildcard_row_is_relevant && matrix . rows () . all (| r | ! r . pats . relevant) { return Ok (WitnessMatrix :: empty ()) ; } let Some (place) = matrix . head_place () else { mcx . increase_complexity_level (matrix . rows () . len ()) ? ; let mut useful = true ; for (i , row) in matrix . rows_mut () . enumerate () { row . useful = useful ; row . intersects_at_least . insert_range (0 .. i) ; useful &= row . is_under_guard ; } return if useful && matrix . wildcard_row_is_relevant { Ok (WitnessMatrix :: unit_witness ()) } else { Ok (WitnessMatrix :: empty ()) } ; } ; let ctors = matrix . heads () . map (| p | p . ctor ()) ; let (split_ctors , missing_ctors) = place . split_column_ctors (mcx . tycx , ctors) ? ; let ty = & place . ty . clone () ; let pcx = & PlaceCtxt { cx : mcx . tycx , ty } ; let mut ret = WitnessMatrix :: empty () ; for ctor in split_ctors { debug ! ("specialize({:?})" , ctor) ; let ctor_is_relevant = matches ! (ctor , Constructor :: Missing) || missing_ctors . is_empty () || mcx . tycx . exhaustive_witnesses () ; let mut spec_matrix = matrix . specialize_constructor (pcx , & ctor , ctor_is_relevant) ? ; let mut witnesses = ensure_sufficient_stack (| | { compute_exhaustiveness_and_usefulness (mcx , & mut spec_matrix) }) ? ; witnesses . apply_constructor (pcx , & missing_ctors , & ctor) ; ret . extend (witnesses) ; if let Constructor :: IntRange (overlap_range) = ctor { if overlap_range . is_singleton () && spec_matrix . rows . len () >= 2 && spec_matrix . rows . iter () . any (| row | ! row . intersects_at_least . is_empty ()) { collect_overlapping_range_endpoints (mcx . tycx , overlap_range , matrix , & spec_matrix) ; } } matrix . unspecialize (spec_matrix) ; } if missing_ctors . iter () . any (| c | matches ! (c , Constructor :: IntRange (..))) { for missing in & missing_ctors { if let Constructor :: IntRange (gap) = missing { if gap . is_singleton () { collect_non_contiguous_range_endpoints (mcx . tycx , gap , matrix) ; } } } } for row in matrix . rows () { if row . head_is_branch { if let PatOrWild :: Pat (pat) = row . head () { mcx . branch_usefulness . entry (pat . uid) . or_default () . update (row , matrix) ; } } } Ok (ret) } #[doc = " Indicates why a given pattern is considered redundant."] #[derive (Clone , Debug)] pub struct RedundancyExplanation < 'p , Cx : PatCx > { #[doc = " All the values matched by this pattern are already matched by the given set of patterns."] #[doc = " This list is not guaranteed to be minimal but the contained patterns are at least guaranteed"] #[doc = " to intersect this pattern."] pub covered_by : Vec < & 'p DeconstructedPat < Cx > > , } #[doc = " Indicates whether or not a given arm is useful."] #[derive (Clone , Debug)] pub enum Usefulness < 'p , Cx : PatCx > { #[doc = " The arm is useful. This additionally carries a set of or-pattern branches that have been"] #[doc = " found to be redundant despite the overall arm being useful. Used only in the presence of"] #[doc = " or-patterns, otherwise it stays empty."] Useful (Vec < (& 'p DeconstructedPat < Cx > , RedundancyExplanation < 'p , Cx >) >) , #[doc = " The arm is redundant and can be removed without changing the behavior of the match"] #[doc = " expression."] Redundant (RedundancyExplanation < 'p , Cx >) , } #[doc = " The output of checking a match for exhaustiveness and arm usefulness."] pub struct UsefulnessReport < 'p , Cx : PatCx > { #[doc = " For each arm of the input, whether that arm is useful after the arms above it."] pub arm_usefulness : Vec < (MatchArm < 'p , Cx > , Usefulness < 'p , Cx >) > , #[doc = " If the match is exhaustive, this is empty. If not, this contains witnesses for the lack of"] #[doc = " exhaustiveness."] pub non_exhaustiveness_witnesses : Vec < WitnessPat < Cx > > , #[doc = " For each arm, a set of indices of arms above it that have non-empty intersection, i.e. there"] #[doc = " is a value matched by both arms. This may miss real intersections."] pub arm_intersections : Vec < DenseBitSet < usize > > , } #[doc = " Computes whether a match is exhaustive and which of its arms are useful."] #[instrument (skip (tycx , arms) , level = "debug")] pub fn compute_match_usefulness < 'p , Cx : PatCx > (tycx : & Cx , arms : & [MatchArm < 'p , Cx >] , scrut_ty : Cx :: Ty , scrut_validity : PlaceValidity , complexity_limit : usize ,) -> Result < UsefulnessReport < 'p , Cx > , Cx :: Error > { if tycx . match_may_contain_deref_pats () { checks :: detect_mixed_deref_pat_ctors (tycx , arms) ? ; } let mut cx = UsefulnessCtxt { tycx , branch_usefulness : FxHashMap :: default () , complexity_limit , complexity_level : 0 , } ; let mut matrix = Matrix :: new (arms , scrut_ty , scrut_validity) ; let non_exhaustiveness_witnesses = compute_exhaustiveness_and_usefulness (& mut cx , & mut matrix) ? ; let non_exhaustiveness_witnesses : Vec < _ > = non_exhaustiveness_witnesses . single_column () ; let arm_usefulness : Vec < _ > = arms . iter () . copied () . map (| arm | { debug ! (? arm) ; let usefulness = cx . branch_usefulness . get (& arm . pat . uid) . unwrap () ; let usefulness = if let Some (explanation) = usefulness . is_redundant () { Usefulness :: Redundant (explanation) } else { let mut redundant_subpats = Vec :: new () ; arm . pat . walk (& mut | subpat | { if let Some (u) = cx . branch_usefulness . get (& subpat . uid) { if let Some (explanation) = u . is_redundant () { redundant_subpats . push ((subpat , explanation)) ; false } else { true } } else { true } }) ; Usefulness :: Useful (redundant_subpats) } ; debug ! (? usefulness) ; (arm , usefulness) }) . collect () ; let arm_intersections : Vec < _ > = matrix . rows () . map (| row | row . intersects_at_least . clone ()) . collect () ; Ok (UsefulnessReport { arm_usefulness , non_exhaustiveness_witnesses , arm_intersections }) }